@using sv_cee83a3561ff4cf793eda65f0456fc28.Models

<div class="d-flex justify-content-between align-items-center mb-4 position-relative">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i;
        var isActive = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);
        var isFuture = !isActive && !isCompleted;

        <div class="text-center flex-fill position-relative" style="z-index: 1;">
            <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepButtonClass(isActive, isCompleted)"
                    style="width: 40px; height: 40px;"
                    disabled="@(isFuture)"
                    @onclick="() => OnStepClick(step)">
                @if (isCompleted)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(step + 1)</span>
                }
            </button>
            <div class="small mt-1 @(isFuture ? "text-muted" : isActive ? "fw-bold" : "")">
                @StepNames[step]
            </div>
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }

    private static string StepButtonClass(bool isActive, bool isCompleted) =>
        isActive ? "btn-primary" :
        isCompleted ? "btn-success" :
        "btn-outline-secondary";
}

