@using sv_cee83a3561ff4cf793eda65f0456fc28.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h6 class="card-title mb-0">Position @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Company" @onchange="e => { Company = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Title" @onchange="e => { Title = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="e => { StartDate = DateTime.Parse(e.Value?.ToString() ?? string.Empty); NotifyChanged(); }" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                       disabled="@IsCurrent"
                       @onchange="e => { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!); NotifyChanged(); }" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" checked="@IsCurrent" @onchange="e => { IsCurrent = (bool)(e.Value ?? false); if (IsCurrent) EndDate = null; NotifyChanged(); }" />
                    <label class="form-check-label">Currently working here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="2" @onchange="e => { Description = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }">@Description</textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public WorkEntry? Model { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntry> OnChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnRemove { get; set; }

    private string Company { get; set; } = "";
    private string Title { get; set; } = "";
    private DateTime StartDate { get; set; } = DateTime.Today;
    private DateTime? EndDate { get; set; }
    private bool IsCurrent { get; set; }
    private string Description { get; set; } = "";

    protected override void OnParametersSet()
    {
        if (Model is not null)
        {
            Company = Model.Company;
            Title = Model.Title;
            StartDate = Model.StartDate;
            EndDate = Model.EndDate;
            IsCurrent = Model.EndDate is null;
            Description = Model.Description;
        }
    }

    private void NotifyChanged()
    {
        var entry = new WorkEntry(Company, Title, StartDate, IsCurrent ? null : EndDate, Description);
        OnChanged.InvokeAsync(entry);
    }
}

