arguments.file_text:
@using sv_cee83a3561ff4cf793eda65f0456fc28.Models

<h4 class="mb-3">Work History</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryForm Index="index"
                   Model="Entries[index]"
                   CanRemove="Entries.Count > 1"
                   OnChanged="entry => UpdateEntry(index, entry)"
                   OnRemove="() => RemoveEntry(index)" />
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public WorkHistory? Model { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkHistory> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<WorkEntry> Entries { get; set; } = new();
    private string? ErrorMessage { get; set; }

    protected override void OnParametersSet()
    {
        if (Model is not null && Model.Entries.Count > 0)
        {
            Entries = Model.Entries.ToList();
        }
        else if (Entries.Count == 0)
        {
            Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
        }
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntry entry)
    {
        if (index < Entries.Count)
        {
            Entries[index] = entry;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Company name and job title are required for all positions.";
                return;
            }
        }

        await OnNext.InvokeAsync(new WorkHistory(Entries.ToList()));
    }
}

@using sv_cee83a3561ff4cf793eda65f0456fc28.Models

<h4 class="mb-3">References</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceForm Index="index"
                   Model="References[index]"
                   CanRemove="References.Count > 2"
                   OnChanged="r => UpdateReference(index, r)"
                   OnRemove="() => RemoveReference(index)" />
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<Reference>? Model { get; set; }
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private List<Reference> References { get; set; } = new();
    private string? ErrorMessage { get; set; }

    protected override void OnParametersSet()
    {
        if (Model is not null && Model.Count > 0)
        {
            References = Model.ToList();
        }
        else if (References.Count == 0)
        {
            References.Add(new Reference("", "", "", ""));
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void UpdateReference(int index, Reference reference)
    {
        if (index < References.Count)
        {
            References[index] = reference;
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All fields are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync(References.ToList());
    }
}

@using sv_cee83a3561ff4cf793eda65f0456fc28.Models

<h4 class="mb-3">Review Your Application</h4>

@if (Personal is not null)
{
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@Personal.FullName</dd>
                <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Personal.Email</dd>
                <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Personal.Phone</dd>
                <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Personal.Address</dd>
            </dl>
        </div>
    </div>
}

@if (Work is not null)
{
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var entry in Work.Entries)
            {
                <div class="mb-2 @(entry != Work.Entries[^1] ? "pb-2 border-bottom" : "")">
                    <strong>@entry.Title</strong> at @entry.Company<br />
                    <small class="text-muted">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mb-0 mt-1">@entry.Description</p>
                    }
                </div>
            }
        </div>
    </div>
}

@if (References is not null)
{
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var r in References)
            {
                <div class="mb-2 @(r != References[^1] ? "pb-2 border-bottom" : "")">
                    <strong>@r.Name</strong> (@r.Relationship)<br />
                    <small>@r.Email &bull; @r.Phone</small>
                </div>
            }
        </div>
    </div>
}

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Cover Letter</strong>
        <button class="btn btn-link btn-sm p-0" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
    </div>
    <div class="card-body">
        <p style="white-space: pre-wrap;" class="mb-0">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(none)" : CoverLetter)</p>
    </div>
</div>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="() => OnBack.InvokeAsync()">Back</button>
    <button class="btn btn-success btn-lg" @onclick="() => OnSubmit.InvokeAsync()" disabled="@IsSubmitting">
        @if (IsSubmitting)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Submit Application
    </button>
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnEdit { get; set; }
    [Parameter, EditorRequired] public EventCallback OnSubmit { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
