@page "/apply"
@using sv_cee83a3561ff4cf793eda65f0456fc28.Models
@inject IApplicationService AppService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (SubmittedId is not null)
    {
        <div class="alert alert-success text-center">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p>Your application has been received. Your confirmation number is:</p>
            <p class="display-6 fw-bold">@SubmittedId</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="CurrentStep"
                       CompletedSteps="CompletedSteps"
                       OnStepClicked="GoToStep" />

        @switch (CurrentStep)
        {
            case 0:
                <PersonalInfoStep Model="PersonalData"
                                  ValidateEmail="AppService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;
            case 1:
                <WorkHistoryStep Model="WorkData"
                                 OnNext="HandleWorkNext"
                                 OnBack="GoBack" />
                break;
            case 2:
                <ReferencesStep Model="ReferencesData"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;
            case 3:
                <CoverLetterStep Model="CoverLetterData"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;
            case 4:
                <ReviewStep Personal="PersonalData"
                            Work="WorkData"
                            References="ReferencesData"
                            CoverLetter="CoverLetterData"
                            IsSubmitting="IsSubmitting"
                            OnEdit="GoToStep"
                            OnSubmit="HandleSubmit"
                            OnBack="GoBack" />
                break;
        }
    }
</div>

@code {
    private int CurrentStep { get; set; }
    private HashSet<int> CompletedSteps { get; set; } = new();
    private bool IsSubmitting { get; set; }
    private int? SubmittedId { get; set; }

    private PersonalInfo? PersonalData { get; set; }
    private WorkHistory? WorkData { get; set; }
    private List<Reference>? ReferencesData { get; set; }
    private string? CoverLetterData { get; set; }

    private void GoToStep(int step) => CurrentStep = step;

    private void GoBack() => CurrentStep = Math.Max(0, CurrentStep - 1);

    private void HandlePersonalNext(PersonalInfo info)
    {
        PersonalData = info;
        CompletedSteps.Add(0);
        CurrentStep = 1;
    }

    private void HandleWorkNext(WorkHistory work)
    {
        WorkData = work;
        CompletedSteps.Add(1);
        CurrentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        ReferencesData = refs;
        CompletedSteps.Add(2);
        CurrentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        CoverLetterData = text;
        CompletedSteps.Add(3);
        CurrentStep = 4;
    }

    private async Task HandleSubmit()
    {
        if (PersonalData is null || WorkData is null || ReferencesData is null)
            return;

        IsSubmitting = true;
        try
        {
            var application = new JobApplication(PersonalData, WorkData, ReferencesData, CoverLetterData ?? "");
            var id = await AppService.SubmitApplicationAsync(application);
            SubmittedId = id;
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

